import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv_transpose2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_conv_transpose2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N,
    int Cin,
    int Hin,
    int Win,
    int Cout,
    int Hout,
    int Wout,
    int Kh,
    int Kw,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w,
    int groups,
    int CinPerGroup,
    int CoutPerGroup,
    int MaxInputTileH,
    int MaxInputTileW)
{
    constexpr int SpatialTileH = 64;
     constexpr int SpatialTileW = 16;
    constexpr int OutputChannelsPerBlock = 4;
    constexpr int ThreadsPerBlock = 256;

    extern __shared__ float shared_memory[];
    float* shared_weight = shared_memory;
    const int weight_count =
        OutputChannelsPerBlock * CinPerGroup * Kh * Kw;
    float* shared_input = shared_memory + weight_count;

    const int tid = threadIdx.x;
    const int tiles_c =
        (CoutPerGroup + OutputChannelsPerBlock - 1) /
        OutputChannelsPerBlock;

    const int batch_group = blockIdx.z;
    const int n = batch_group / groups;
    const int group = batch_group % groups;

    const int combined_tile = blockIdx.y;
    const int channel_tile = combined_tile % tiles_c;
    const int tile_y = combined_tile / tiles_c;
    const int tile_x = blockIdx.x;

    auto x_at = [&](int n_, int c_, int y_, int x_) -> float {
        const int64_t offset =
            (((int64_t)n_ * Cin + c_) * Hin + y_) * Win + x_;
        return x[offset];
    };

    auto w_at = [&](int ic_, int oc_, int ky_, int kx_) -> float {
        const int64_t offset =
            (((int64_t)ic_ * CoutPerGroup + oc_) * Kh + ky_) * Kw + kx_;
        return weight[offset];
    };

    auto y_at = [&](int n_, int oc_, int y_, int x_) -> float& {
        const int64_t offset =
            (((int64_t)n_ * Cout + oc_) * Hout + y_) * Wout + x_;
        return output[offset];
    };

    auto sw_at = [&](int oc_, int ic_, int ky_, int kx_) -> float& {
        const int64_t offset =
            (((int64_t)oc_ * CinPerGroup + ic_) * Kh + ky_) * Kw + kx_;
        return shared_weight[offset];
    };

    for (int linear = tid; linear < weight_count; linear += ThreadsPerBlock) {
        int t = linear;
        const int oc_local = t / (CinPerGroup * Kh * Kw);
        t %= CinPerGroup * Kh * Kw;
        const int ic_local = t / (Kh * Kw);
        t %= Kh * Kw;
        const int ky = t / Kw;
        const int kx = t % Kw;
        const int oc_global = channel_tile * OutputChannelsPerBlock + oc_local;

        if (oc_global < CoutPerGroup) {
            const int ic_global = group * CinPerGroup + ic_local;
            sw_at(oc_local, ic_local, ky, kx) =
                w_at(ic_global, oc_global, ky, kx);
        } else {
            sw_at(oc_local, ic_local, ky, kx) = 0.0f;
        }
    }

    const int y_start_num =
        tile_y * SpatialTileH + pad_h - (Kh - 1) * dil_h;
    const int x_start_num =
        tile_x * SpatialTileW + pad_w - (Kw - 1) * dil_w;

    const int y_origin =
        y_start_num >= 0
            ? y_start_num / stride_h
            : -((-y_start_num + stride_h - 1) / stride_h);
    const int x_origin =
        x_start_num >= 0
            ? x_start_num / stride_w
            : -((-x_start_num + stride_w - 1) / stride_w);

    const int tile_input_h =
        max(0, min(MaxInputTileH, Hin - max(y_origin, 0)));
    const int tile_input_w =
        max(0, min(MaxInputTileW, Win - max(x_origin, 0)));
    const int tile_input_area = tile_input_h * tile_input_w;

    const int total_input_values = CinPerGroup * tile_input_area;
    const int chunks_per_row = (tile_input_w + 3) / 4;
    const int total_input_chunks =
        CinPerGroup * tile_input_h * chunks_per_row;
    for (int linear = tid; linear < total_input_chunks;
         linear += ThreadsPerBlock) {
        const int ic_local = linear / (tile_input_h * chunks_per_row);
        const int rem = linear % (tile_input_h * chunks_per_row);
        const int sy = rem / chunks_per_row;
        const int sx = (rem % chunks_per_row) * 4;
        const int iy = y_origin + sy;
        const int ix = x_origin + sx;
        const int shared_index =
            ic_local * MaxInputTileH * MaxInputTileW +
            sy * MaxInputTileW + sx;
        if (iy >= 0 && iy < Hin && ix >= 0 && ix + 3 < Win &&
            sx + 3 < tile_input_w) {
            const int64_t global_offset =
                (((int64_t)n * Cin + group * CinPerGroup + ic_local) *
                 Hin + iy) * Win + ix;
            const float* src = x + global_offset;
            if ((reinterpret_cast<uintptr_t>(src) & 15u) == 0u) {
                const float4 v = *reinterpret_cast<const float4*>(src);
                shared_input[shared_index + 0] = v.x;
                shared_input[shared_index + 1] = v.y;
                shared_input[shared_index + 2] = v.z;
                shared_input[shared_index + 3] = v.w;
            } else {
                for (int k = 0; k < 4; ++k) {
                    shared_input[shared_index + k] =
                        x_at(n, group * CinPerGroup + ic_local, iy, ix + k);
                }
            }
        } else {
            for (int k = 0; k < 4 && sx + k < tile_input_w; ++k) {
                const int cur_x = ix + k;
                if (iy >= 0 && iy < Hin && cur_x >= 0 && cur_x < Win) {
                    shared_input[shared_index + k] =
                        x_at(n, group * CinPerGroup + ic_local, iy, cur_x);
                } else {
                    shared_input[shared_index + k] = 0.0f;
                }
            }
        }
    }

    __syncthreads();

    constexpr int SpatialTileArea = SpatialTileH * SpatialTileW;
     const int output_linear_base = tid * 16;
    for (int output_pair = 0; output_pair < 16; ++output_pair) {
        const int output_linear = output_linear_base + output_pair;
        const int oc_local = output_linear / SpatialTileArea;
        const int spatial_index = output_linear % SpatialTileArea;
        const int oc_in_group =
            channel_tile * OutputChannelsPerBlock + oc_local;
        const bool valid_channel = n < N && oc_in_group < CoutPerGroup;
        const int oy = tile_y * SpatialTileH + spatial_index / SpatialTileW;
        const int ox = tile_x * SpatialTileW + spatial_index % SpatialTileW;
    const bool valid_output =
        n < N &&
        oc_in_group < CoutPerGroup &&
        oy >= 0 && oy < Hout &&
        ox >= 0 && ox < Wout;
    if (!valid_output) {
        continue;
    }
    float acc = 0.0f;
    for (int ic_local = 0; ic_local < CinPerGroup; ++ic_local) {
        for (int ky = 0; ky < Kh; ++ky) {
            const int numerator_y = oy + pad_h - ky * dil_h;
            if (numerator_y < 0 || numerator_y % stride_h != 0) {
                continue;
            }
            const int iy = numerator_y / stride_h;
            if (iy < 0 || iy >= Hin) {
                continue;
            }
            for (int kx = 0; kx < Kw; ++kx) {
                const int numerator_x = ox + pad_w - kx * dil_w;
                if (numerator_x < 0 || numerator_x % stride_w != 0) {
                    continue;
                }
                const int ix = numerator_x / stride_w;
                if (ix < 0 || ix >= Win) {
                    continue;
                }
                const int sy = iy - y_origin;
                const int sx = ix - x_origin;
                if (sy >= 0 && sy < tile_input_h &&
                    sx >= 0 && sx < tile_input_w) {
                    const int shared_index =
                        ic_local * MaxInputTileH * MaxInputTileW +
                        sy * MaxInputTileW + sx;
                    acc += shared_input[shared_index] *
                           sw_at(oc_local, ic_local, ky, kx);
                }
            }
        }
    }
    const int oc = group * CoutPerGroup + oc_in_group;
    if (bias != nullptr) {
        acc += bias[oc];
    }
    y_at(n, oc, oy, ox) = acc;
    }  // output_pair loop
    }


torch::Tensor cute_conv_transpose2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(!bias.defined() || bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat,
                "weight must be float32");
    const bool has_bias = bias.defined() && bias.numel() != 0;
    TORCH_CHECK(!has_bias || bias.scalar_type() == at::kFloat,
                "bias must be float32");

    TORCH_CHECK(x.dim() == 4, "x must be 4D");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(stride_h > 0 && stride_w > 0,
                "stride must be positive");
    TORCH_CHECK(pad_h >= 0 && pad_w >= 0,
                "padding must be nonnegative");
    TORCH_CHECK(dil_h > 0 && dil_w > 0,
                "dilation must be positive");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = has_bias ? bias.contiguous() : torch::Tensor();

    const int N = static_cast<int>(x_c.size(0));
    const int Cin = static_cast<int>(x_c.size(1));
    const int Hin = static_cast<int>(x_c.size(2));
    const int Win = static_cast<int>(x_c.size(3));

    const int Kh = static_cast<int>(w_c.size(2));
    const int Kw = static_cast<int>(w_c.size(3));

    TORCH_CHECK(Cin % groups == 0, "input channels must divide groups");
    TORCH_CHECK(w_c.size(0) == Cin,
                "weight.size(0) must equal input channels");

    const int CinPerGroup = Cin / static_cast<int>(groups);
    const int CoutPerGroup = static_cast<int>(w_c.size(1));
    const int Cout = CoutPerGroup * static_cast<int>(groups);

    TORCH_CHECK(
        !has_bias ||
        (b_c.dim() == 1 && b_c.size(0) == Cout),
        "bias must have shape (out_channels,)");
    const int Hout =
        (Hin - 1) * static_cast<int>(stride_h) -
        2 * static_cast<int>(pad_h) +
        static_cast<int>(dil_h) * (Kh - 1) + 1;

    const int Wout =
        (Win - 1) * static_cast<int>(stride_w) -
        2 * static_cast<int>(pad_w) +
        static_cast<int>(dil_w) * (Kw - 1) + 1;

    TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output dimensions");

    auto output = torch::empty(
        {N, Cout, Hout, Wout},
        x_c.options());

     constexpr int SpatialTileH = 64;
      constexpr int SpatialTileW = 16;
     constexpr int OutputChannelsPerBlock = 4;
     constexpr int ThreadsPerBlock = 256;

    const int tiles_w = (Wout + SpatialTileW - 1) / SpatialTileW;
    const int tiles_h = (Hout + SpatialTileH - 1) / SpatialTileH;
    const int tiles_c =
        (CoutPerGroup + OutputChannelsPerBlock - 1) /
        OutputChannelsPerBlock;

    dim3 block(ThreadsPerBlock);
    dim3 grid(
        tiles_w,
        tiles_h * tiles_c,
        N * static_cast<int>(groups));

    const int max_input_tile_h =
        std::min(Hin, ((Kh - 1) * static_cast<int>(dil_h) +
                       SpatialTileH - 1) /
                          static_cast<int>(stride_h) +
                      2);
    const int max_input_tile_w =
        std::min(Win, ((Kw - 1) * static_cast<int>(dil_w) +
                       SpatialTileW - 1) /
                          static_cast<int>(stride_w) +
                      2);

    const size_t shared_bytes =
        (static_cast<size_t>(OutputChannelsPerBlock) *
             static_cast<size_t>(CinPerGroup) *
             static_cast<size_t>(Kh) *
             static_cast<size_t>(Kw) +
         static_cast<size_t>(CinPerGroup) *
             static_cast<size_t>(max_input_tile_h) *
             static_cast<size_t>(max_input_tile_w)) *
        sizeof(float);

    const float* bias_ptr =
        has_bias ? b_c.data_ptr<float>() : nullptr;

    cudaStream_t stream =
        c10::cuda::getCurrentCUDAStream().stream();

    cute_conv_transpose2d_kernel<<<grid, block, shared_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N,
        Cin,
        Hin,
        Win,
        Cout,
        Hout,
        Wout,
        Kh,
        Kw,
        static_cast<int>(stride_h),
        static_cast<int>(stride_w),
        static_cast<int>(pad_h),
        static_cast<int>(pad_w),
        static_cast<int>(dil_h),
        static_cast<int>(dil_w),
        static_cast<int>(groups),
        CinPerGroup,
        CoutPerGroup,
        max_input_tile_h,
        max_input_tile_w);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE transposed convolution launch failed");

    return output;
}
"""


cute_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
        "--expt-extended-lambda",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

        self.stride_h = int(stride[0])
        self.stride_w = int(stride[1])
        self.pad_h = int(padding[0])
        self.pad_w = int(padding[1])
        self.dil_h = int(dilation[0])
        self.dil_w = int(dilation[1])
        self.groups = int(groups)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose2d.bias
        if bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )

        return cute_ext.cute_conv_transpose2d(
            x,
            self.conv_transpose2d.weight,
            bias,
            self.stride_h,
            self.stride_w,
            self.pad_h,
            self.pad_w,
            self.dil_h,
            self.dil_w,
            self.groups,
        )

